//! Intl.Collator.prototype.resolvedOptions ( )
//!
//! Spec: https://tc39.es/ecma402/#sec-intl.collator.prototype.resolvedoptions

use kahvi_core::prelude::*;

use crate::support::intl_collator::{
    CollatorSlots, RELEVANT_EXTENSION_KEYS, require_collator,
};

/// Intl.Collator.prototype.resolvedOptions
pub(crate) fn prototype_resolved_options(
    agent: &mut Agent,
    this: Value,
    args: &[Value],
    new_target: Option<Object>,
) -> JsResult<Value> {
    // This function provides access to the locale and options computed during initialization of the object.
    //
    let _ = (args, new_target);
    // 1. Let _collator_ be the *this* value.
    // 2. Perform ? RequireInternalSlot(_collator_, [[InitializedCollator]]).
    let collator = require_collator(agent, this)?;
    // 3. Let _options_ be OrdinaryObjectCreate(%Object.prototype%).
    let object_prototype = agent.intrinsic("%Object.prototype%");
    let options = agent.ordinary_object_create(Some(object_prototype));
    // 4. For each row of [table-collator-resolvedoptions-properties], except the header row, in table order, do
    let rows: Vec<(&str, Option<&str>, Value)> = {
        let Some(slots) = agent.native::<CollatorSlots>(collator) else {
            return Err(agent.throw_type_error("not an Intl.Collator"));
        };
        let (locale, usage, sensitivity, collation, case_first) = (
            slots.locale.clone(),
            slots.usage.clone(),
            slots.sensitivity.clone(),
            slots.collation.clone(),
            slots.case_first.clone(),
        );
        let (ignore_punctuation, numeric) = (slots.ignore_punctuation, slots.numeric);
        let mut string = |s: String| Value::String(agent.string(&s));
        vec![
            ("locale", None, string(locale)),
            ("usage", None, string(usage)),
            ("sensitivity", None, string(sensitivity)),
            ("ignorePunctuation", None, Value::Boolean(ignore_punctuation)),
            ("collation", None, string(collation)),
            ("numeric", Some("kn"), Value::Boolean(numeric)),
            ("caseFirst", Some("kf"), string(case_first)),
        ]
    };
    for (property, extension_key, value) in rows {
        //    a. Let _propertyKey_ be the Property value of the current row.
        let property_key = agent.key(property);
        //    b. Let _value_ be the value of _collator_'s internal slot whose name is the Internal Slot value of the current row.
        let mut value = value;
        //    c. If the current row has an Extension Key value, then
        if let Some(extension_key) = extension_key {
            //       i. Let _extensionKey_ be the Extension Key value of the current row.
            //       ii. If %Intl.Collator%.[[RelevantExtensionKeys]] does not contain _extensionKey_, then
            if !RELEVANT_EXTENSION_KEYS.contains(&extension_key) {
                //          1. Set _value_ to *undefined*.
                value = Value::Undefined;
            }
        }
        //    d. If _value_ is not *undefined*, then
        if !matches!(value, Value::Undefined) {
            //       i. Perform ! CreateDataPropertyOrThrow(_options_, _propertyKey_, _value_).
            ops::create_data_property_or_throw(agent, options, property_key, value)?;
        }
    }
    // 5. Return _options_.
    Ok(Value::Object(options))
}
